export type Selected<S extends string>=S extends keyof SelectorElements?SelectorElements[S]:HTMLElement;
export function element<S extends string>(selector:S,root:ParentNode=document):Selected<S> {return required(root.querySelector(selector),'Missing element: '+selector) as Selected<S>;}
export function optionalElement<S extends string>(selector:S,root:ParentNode=document):Selected<S>|null {return root.querySelector(selector) as Selected<S>|null;}
export function control(event:Event):HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement {const target=event.currentTarget??event.target;if(target instanceof HTMLInputElement||target instanceof HTMLSelectElement||target instanceof HTMLTextAreaElement)return target;throw new Error('Expected a form control');}
